<?php

declare(strict_types=1);

namespace Domain\Tasks\Calls;

use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use Domain\Tasks\Http\Data\AssignedTaskListData;

/**
 * The signed calls of Tasks, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class TaskCalls
{
    public function __construct(private CallSender $sender) {}

    public function createTask(
        string $title,
        string $brief,
        CallKey $requestKey = new CallKey(),
    ): TaskNamed {
        return $this->sender->send(CreateTaskCall::from([
            'title' => $title,
            'brief' => $brief,
            'requestKey' => $requestKey,
        ]));
    }

    public function editTask(
        string $taskId,
        int $expectedRevision,
        string|null $title,
        string|null $brief,
        CallKey $requestKey = new CallKey(),
    ): TaskEdited {
        return $this->sender->send(EditTaskCall::from([
            'taskId' => $taskId,
            'expectedRevision' => $expectedRevision,
            'title' => $title,
            'brief' => $brief,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $states
     */
    public function listAssignedTasks(
        string|null $search = null,
        array $states = [],
        int $page = 1,
        int $perPage = 20,
    ): AssignedTaskListData {
        return $this->sender->send(ListAssignedTasksCall::from([
            'search' => $search,
            'states' => $states,
            'page' => $page,
            'perPage' => $perPage,
        ]));
    }
}
